    // Replay first (in emission order), then the live broadcast. Terminate the
    // whole stream when the daemon shuts down so this connection can't pin
    // graceful shutdown open (OCEAN-300).
    //
    // OCEAN-305: a 3s keepalive (down from axum's 15s default) so the TUI's
    // scope-change watcher — which only wakes on incoming lines, including
    // keepalive comments — notices a session switch and re-scopes its
    // subscription within ~3s instead of ~15s. OCEAN-368: the legacy
    // `/v1/events` rail now shares this same `SSE_KEEPALIVE_INTERVAL` contract.
    let stream = tokio_stream::iter(replay_events).chain(live);
    let stream = sse_until_shutdown(stream, state.shutdown.clone());
    Sse::new(stream).keep_alive(KeepAlive::new().interval(SSE_KEEPALIVE_INTERVAL))
}

#[derive(Debug, serde::Deserialize)]
struct SessionProjectionEventsQuery {
    session_id: AgentSessionId,
    after_cursor: String,
    lease_id: String,
}

fn projection_request_cursor(
    headers: &HeaderMap,
    query_cursor: &str,
) -> Result<String, session_projection::ProjectionReset> {
    match headers.get("last-event-id") {
        None => Ok(query_cursor.to_string()),
        Some(value) => {
            let cursor = value
                .to_str()
                .map_err(|_| session_projection::ProjectionReset::Malformed)?;
            if cursor.is_empty() {
                Err(session_projection::ProjectionReset::Malformed)
            } else {
                Ok(cursor.to_string())
            }
        }
    }
}

async fn send_projection_sse(
    tx: &mpsc::Sender<Result<Event, Infallible>>,
    shutdown: &CancellationToken,
    event: Event,
) -> bool {
    tokio::select! {
        biased;
        _ = shutdown.cancelled() => false,
        _ = tx.closed() => false,
        result = tx.send(Ok(event)) => result.is_ok(),
    }
}

async fn send_projection_sse_until(
    tx: &mpsc::Sender<Result<Event, Infallible>>,
    shutdown: &CancellationToken,
    deadline: tokio::time::Instant,
    event: Event,
) -> bool {
    tokio::select! {
        biased;
        _ = shutdown.cancelled() => false,
        _ = tx.closed() => false,
        _ = tokio::time::sleep_until(deadline) => false,
        result = tx.send(Ok(event)) => result.is_ok(),
    }
}

/// Durable session-projection SSE tail. SQLite is authoritative; the broadcast
/// receiver is only a wake hint. Subscribe-before-page plus paging on lag closes
/// the snapshot/live seam without depending on the legacy UUID replay ring.
async fn session_projection_events(
    State(state): State<AppState>,
    Query(query): Query<SessionProjectionEventsQuery>,
    headers: HeaderMap,
) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
    let (tx, rx) = mpsc::channel(64);
    let shutdown = state.shutdown.clone();
    let stream_shutdown = state.shutdown.clone();
    let session_id = query.session_id.to_string();
    let cursor_result = projection_request_cursor(&headers, &query.after_cursor);
    let lease_id = query.lease_id;
    let projection = state.agent_events.projection();

    tokio::spawn(async move {
        let Some(store) = projection else {
            let data = json!({ "type": "projection_reset", "reason": "projection_unavailable" })
                .to_string();
            let _ = send_projection_sse(
                &tx,
                &shutdown,
                Event::default().event("projection_reset").data(data),
            )
            .await;
            return;
        };

        // Register before validating/acknowledging the HTTP request cursor. Any
        // append racing the first page is either visible in SQLite or leaves a
        // buffered wake. Internal pages renew expiry but never acknowledge their
        // queued tail; only this new request (query or Last-Event-ID) advances the
        // lease minimum.
        let mut wakes = store.subscribe();
        let mut cursor = match cursor_result {
            Ok(cursor) => cursor,
            Err(reset) => {
                let data =
                    json!({ "type": "projection_reset", "reason": reset.reason() }).to_string();
                let _ = send_projection_sse(
                    &tx,
                    &shutdown,
                    Event::default().event("projection_reset").data(data),
                )
                .await;
                return;
            }
        };
        if let Err(reset) = store.begin_tail_request(&session_id, &cursor, &lease_id) {
            let data = json!({ "type": "projection_reset", "reason": reset.reason() }).to_string();
            let _ = send_projection_sse(
                &tx,
                &shutdown,
                Event::default().event("projection_reset").data(data),
            )
            .await;
            return;
        }
        let connection_deadline = tokio::time::Instant::now() + store.connection_lifetime();
        loop {
            if tokio::time::Instant::now() >= connection_deadline {
                return;
            }
            match store.page_after(&session_id, &cursor, &lease_id) {
                Ok(frames) if !frames.is_empty() => {
                    for frame in frames {
                        cursor = frame.cursor.clone();
                        let data = serde_json::to_string(&frame).unwrap_or_else(|_| {
                            json!({ "type": "projection_reset", "reason": "serialize_failed" })
                                .to_string()
                        });
                        if !send_projection_sse_until(
                            &tx,
                            &shutdown,
                            connection_deadline,
                            Event::default()
                                .id(frame.cursor)
                                .event("session_projection")
                                .data(data),
                        )
                        .await
                        {
                            return;
                        }
                    }
                    continue;
                }
                Ok(_) => {}
                Err(reset) => {
                    let data = json!({
                        "type": "projection_reset",
                        "reason": reset.reason(),
                    })
                    .to_string();
                    let _ = send_projection_sse_until(
                        &tx,
                        &shutdown,
                        connection_deadline,
                        Event::default().event("projection_reset").data(data),
                    )
                    .await;
                    return;
                }
            }

            tokio::select! {
                _ = shutdown.cancelled() => return,
                _ = tx.closed() => return,
                _ = tokio::time::sleep_until(connection_deadline) => return,
                wake = wakes.recv() => match wake {
                    Ok(woken_session) if woken_session == session_id => {},
                    Ok(_) => continue,
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => {},
                    Err(tokio::sync::broadcast::error::RecvError::Closed) => return,
                }
            }
        }
    });

    let stream = sse_until_shutdown(ReceiverStream::new(rx), stream_shutdown);
    Sse::new(stream).keep_alive(KeepAlive::new().interval(SSE_KEEPALIVE_INTERVAL))
}

/// Parse a truthy SSE query flag (`?all=`, `?replay=`): `1`/`true`/`yes`/`on`.
fn query_flag_truthy(value: Option<&str>) -> bool {
    value.is_some_and(|value| matches!(value, "1" | "true" | "yes" | "on"))
}

/// OCEAN-305: whether a `/v1/agent/events` subscribe should snapshot the FULL
/// history buffer for replay. Only when the client explicitly asked
/// (`?replay=1`), carries no `Last-Event-ID` anchor (an anchor is more precise
/// — honor it instead), and is session-scoped (an unscoped subscriber gets no
/// session-bearing events anyway; never snapshot the firehose for it).
fn use_full_replay(
    replay_requested: bool,
    last_event_id: Option<Uuid>,
    want: Option<AgentSessionId>,
) -> bool {
    replay_requested && last_event_id.is_none() && want.is_some()
}

