    Query(query): Query<SessionProjectionEventsQuery>,
    headers: HeaderMap,
) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
    let (tx, rx) = mpsc::channel(64);
    let shutdown = state.shutdown.clone();
    let stream_shutdown = state.shutdown.clone();
    let session_id = query.session_id.to_string();
    let cursor_result = projection_request_cursor(&headers, &query.after_cursor);
    let lease_id = query.lease_id;
    let projection = state.agent_events.projection();

    tokio::spawn(async move {
        let Some(store) = projection else {
            let data = json!({ "type": "projection_reset", "reason": "projection_unavailable" })
                .to_string();
            let _ = send_projection_sse(
                &tx,
                &shutdown,
                Event::default().event("projection_reset").data(data),
            )
            .await;
            return;
        };

        // Register before validating/acknowledging the HTTP request cursor. Any
        // append racing the first page is either visible in SQLite or leaves a
        // buffered wake. Internal pages renew expiry but never acknowledge their
        // queued tail; only this new request (query or Last-Event-ID) advances the
        // lease minimum.
        let mut wakes = store.subscribe();
        let mut cursor = match cursor_result {
            Ok(cursor) => cursor,
            Err(reset) => {
                let data =
                    json!({ "type": "projection_reset", "reason": reset.reason() }).to_string();
                let _ = send_projection_sse(
                    &tx,
                    &shutdown,
                    Event::default().event("projection_reset").data(data),
                )
                .await;
                return;
            }
        };
        if let Err(reset) = store.begin_tail_request(&session_id, &cursor, &lease_id) {
            let data = json!({ "type": "projection_reset", "reason": reset.reason() }).to_string();
            let _ = send_projection_sse(
                &tx,
                &shutdown,
                Event::default().event("projection_reset").data(data),
            )
            .await;
            return;
        }
        let connection_deadline = tokio::time::Instant::now() + store.connection_lifetime();
        loop {
            if tokio::time::Instant::now() >= connection_deadline {
                return;
            }
            match store.page_after(&session_id, &cursor, &lease_id) {
                Ok(frames) if !frames.is_empty() => {
                    for frame in frames {
                        cursor = frame.cursor.clone();
                        let data = serde_json::to_string(&frame).unwrap_or_else(|_| {
                            json!({ "type": "projection_reset", "reason": "serialize_failed" })
                                .to_string()
                        });
                        if !send_projection_sse_until(
                            &tx,
                            &shutdown,
                            connection_deadline,
                            Event::default()
                                .id(frame.cursor)
                                .event("session_projection")
                                .data(data),
                        )
                        .await
                        {
                            return;
                        }
                    }
                    continue;
                }
                Ok(_) => {}
                Err(reset) => {
                    let data = json!({
                        "type": "projection_reset",
                        "reason": reset.reason(),
                    })
                    .to_string();
                    let _ = send_projection_sse_until(
                        &tx,
                        &shutdown,
                        connection_deadline,
                        Event::default().event("projection_reset").data(data),
                    )
                    .await;
                    return;
                }
            }

            tokio::select! {
                _ = shutdown.cancelled() => return,
                _ = tx.closed() => return,
                _ = tokio::time::sleep_until(connection_deadline) => return,
                wake = wakes.recv() => match wake {
                    Ok(woken_session) if woken_session == session_id => {},
                    Ok(_) => continue,
                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => {},
                    Err(tokio::sync::broadcast::error::RecvError::Closed) => return,
                }
            }
        }
    });

    let stream = sse_until_shutdown(ReceiverStream::new(rx), stream_shutdown);
    Sse::new(stream).keep_alive(KeepAlive::new().interval(SSE_KEEPALIVE_INTERVAL))
}

